#include <FreeRTOS.h>
#include <task.h>
#include <stdio.h>

void vTaskFunction(void *pvParameters) {
    for (;;) {
        printf("Task running\n");
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}

int main(void) {
    xTaskCreate(vTaskFunction, "Task", 256, NULL, 1, NULL);
    vTaskStartScheduler();
    return 0;
}
